Connector.ConnectorScript:
task.logmsg("<!--- bindSrv1 ::  try to bind to a specific directory directory --->");

 persistLDAPCreds(work.getObject("ldap.dn"), work.getObject("ldap.password"));
 var ldapcon = initLDAPConn("1", "Iterator");
 if( ldapcon == null ) {
	task.logmsg("<*** ERROR: bindSrv1 :: bind op failed ***>");
	work.setAttribute("ldap.status", "1");
 } else {
		task.logmsg("<!-- Bind succeeded -->");		
		// set the binddn and passwd in the property store.
}

 task.logmsg("<!--- bindSrv2 :: try to bind to the second directory server --->");
 ldapcon = initLDAPConn( "2", "Iterator" );
 persistLDAPCreds(work.getObject("ldap.dn"), work.getObject("ldap.password"));
 if( ldapcon == null ) {
	task.logmsg("<!*** bindSrv2 :: bind failed again ***>");
 } else {
		task.logmsg("the ldap.ip is: " +work.getObject("ldap.ipaddress"));
		task.logmsg("<!-- bindSrv2 :: Bind succeeded -->");	
		work.setAttribute("ldap.status", "0");
		work.setAttribute("ldap.ip", work.getObject("ldap.ipaddress"));	
 }

task.logmsg("<!-- pagedSearch :: paged search -->");
task.logmsg("pagedSearch: cookie = #" + work.getString("ldap.pagedsearch.cookie") + "#");

// Make sure we have an AL on our first call
var cookie = work.getString("ldap.pagedsearch.cookie");
if ( cookie == null || cookie.length() == 0 ) {
	task.logmsg("<!-- Starting SearchAL for paged search -->");
	searchAL = loadSearchAL();
} else {
	task.logmsg("<!-- Sending next page in paged search -->");
}

if ( searchAL == null ) {
	task.logmsg("<!*** ERROR: no SearchAL exists for paged search -->");
	work.setAttribute("ldap.status", "1");
	work.setAttribute("ldap.errormessage", "Paged search continued without a current search AL");

} else {

	// Send next page
	task.logmsg("<!-- send next page -->");
	result = sendResults(ldapSrv_listener, work.getString("ldap.pagedsearch.pagesize"));

	// Set cookie if we have more results
	if ( result )
		work.setAttribute("ldap.pagedsearch.cookie", "moredata");
	else
		work.setAttribute("ldap.pagedsearch.cookie", "");

	// Set status and error messages
	task.logmsg("<!-- set reply codes -->");
	setReplyCodes(result);
}

task.logmsg("<!-- simpleSearch :: simple search -->");

if(work.getObject("ldap.searchbase") != "") {
	// Make sure we have an AL
	searchAL = loadSearchAL();

	// Send the search results
	result = sendResults(ldapSrv_listener, 0);

	// Set status and error messages
	setReplyCodes(result);
} else {
	if(work.getObject("ldap.scope") == "base") {
		task.logmsg(" --- performing rootdse search --- ");	
		ldapSrv_listener.connector.putEntry(ldapcon.getServerInfo());		
	} else {
	// Make sure we have an AL
	searchAL = loadSearchAL();

	// Send the search results
	result = sendResults(ldapSrv_listener, 0);

	// Set status and error messages
	setReplyCodes(result);
	}
}

task.logmsg("<!--- ldap.abandon --->");
abanid = work.getObject("ldap.messageid");
if ( ldapSrv_listener.connector.isAbandoned(abanid) ) {
		task.logmsg("REQUEST ABANDONED: " + abanid);
		searchAL.shutdown();
	}
work.setAttribute("ldap.status", "0");

Script.parameter:
/////////////////////////////////////////////////////////////////////////
//	function:	setInputParams
//	Version:	1.0
//
// 	Description: 
//				Set runtime params for the input connector
/////////////////////////////////////////////////////////////////////////
function setInputParams( myTcb) {

	task.logmsg("<!-- setInputParameters -->");
	myTcb.setConnectorParameter("input", "ldapSearchFilter", work.getObject("ldap.searchfilter") );
	myTcb.setConnectorParameter("input", "ldapSearchScope", getSearchScope(work.getObject("ldap.scope")) );	
	myTcb.setConnectorParameter("input", "ldapSearchBase", work.getObject("ldap.searchbase") );	
	myTcb.setConnectorParameter("input", "ldapUsername", getPersistentObject("ldap.dn") );	
	myTcb.setConnectorParameter("input", "ldapPassword", getPersistentObject("ldap.password") );
	myTcb.setConnectorParameter("input", "ldapTimeLimit", work.getObject("ldap.timelimit") );
	myTcb.setConnectorParameter("input", "ldapSizeLimit", work.getObject("ldap.sizelimit") );
	myTcb.setConnectorParameter("input", "ldapPageSize", work.getObject("ldap.pagedsearch.pagesize") );
	myTcb.setConnectorParameter("input", "ldapReturnAttributes", getRetAttrList() );

}

/////////////////////////////////////////////////////////////////////////
//	function:	persistLDAPCreds
//	Version:	1.0
//
// 	Description: 
//				sets a named value to the default persistent store 
/////////////////////////////////////////////////////////////////////////
function persistLDAPCreds( binddn, passwd ) {
	system.setPersistentObject( "ldap.dn", binddn );
	system.setPersistentObject( "ldap.password", passwd );
}

/////////////////////////////////////////////////////////////////////////
//	function:	initLDAPConn
//	Version:	1.0
//
// 	Description: 
//				Initializes the LDAPConnector 
/////////////////////////////////////////////////////////////////////////

function initLDAPConn( name, mode ) {

	var conn = system.getConnector(getTDIProperty("CONN_"+name));
	// the connector mode for iteration.
	var connMode = new Packages.com.ibm.di.server.ConnectorMode(mode);

	task.logmsg("the username is: " +work.getObject("ldap.dn"));
	task.logmsg("<!-- Initializing -->" +getTDIProperty("CONN_"+name));
	task.logmsg("the username from PS: " +getPersistentObject("ldap.dn"));
	task.logmsg("the passwd from PS: " +getPersistentObject("ldap.password"));
	task.logmsg("the ldapurl is: " +getTDIProperty("LDAP_URL_"+name));

	// get the credentials and other attributes from the work entry and try to bind.
	conn.setParam("ldapUrl", getTDIProperty("LDAP_URL_"+name));
	conn.setParam("ldapUsername", 		getPersistentObject("ldap.dn"));
	conn.setParam("ldapPassword", 		getPersistentObject("ldap.password"));
	if(work.getObject("ldap.bindmethod")!=null){
		conn.setParam("ldapAuthenticationMethod", 	work.getObject("ldap.bindmethod"));
	}else{
		task.logmsg("using simple auth");
		conn.setParam("ldapAuthenticationMethod", 	"simple");
	}
	conn.setParam("ldapSearchbase", 	work.getObject("ldap.searchbase"));
	conn.setParam("ldapSearchFilter", 	work.getObject("ldap.searchfilter"));
	conn.setParam("ldapSearchScope", 	work.getObject("ldap.scope"));
    conn.setParam("ldapTimeLimit", work.getObject("ldap.timelimit"));
    conn.setParam("ldapSizeLimit", work.getObject("ldap.sizelimit"));

	try {
		conn.initialize ( connMode );
		task.logmsg("<!-- connector Initialized in mode: -->" +mode);
		return conn;
	}catch(Ex) {
		task.logmsg("<!**** initLDAPConn :: LDAPConn failed to initailize: ***>" +Ex);
		return null;
	}
}

/////////////////////////////////////////////////////////////////////////
//	function:	getTDIProperty
//	Version:	1.0
//
// 	Description: 
//				gets a named value from the default property store 
/////////////////////////////////////////////////////////////////////////
function getTDIProperty( key ) {
	return ( main.getMetamergeConfig().getTDIProperties().getProperty( key ) );
}

/////////////////////////////////////////////////////////////////////////
//	function:	getSearchScope
//	Version:	1.0
//
// 	Description: 
//				sets a named value to the default persistent store 
/////////////////////////////////////////////////////////////////////////
function getSearchScope( srchScope ) {
	 if (srchScope.equalsIgnoreCase("base")) {
		return "baselevel";
	 } else if (srchScope.equalsIgnoreCase("onelevel")) {
		return "onelevel";
	 } else if (srchScope.equalsIgnoreCase("subtree")) {
	 	return "subtree";
	 }
}

/////////////////////////////////////////////////////////////////////////
//	function:	getReturnAttrList
//	Version:	1.0
//
// 	Description: 
//				sets a named value to the default persistent store 
/////////////////////////////////////////////////////////////////////////
function getRetAttrList() {
	attrList = work.getAttribute("ldap.attributes").getValuesVector();
	str = "";
	for(i = 0 ; i < attrList.size(); i++ ) {
		str = str + attrList.elementAt(i) + "\r\n";
	}
	return str;
}

/////////////////////////////////////////////////////////////////////////
//	function:	getPersistentObject
//	Version:	1.0
//
// 	Description: 
//				sets a named value to the default persistent store 
/////////////////////////////////////////////////////////////////////////
function getPersistentObject( key ) {
	 return (system.getPersistentObject( key ));
}

/////////////////////////////////////////////////////////////////////////
//	function:	compare
//	Version:	1.0
//
// 	Description: 
//				compare an entry
/////////////////////////////////////////////////////////////////////////
function compare(connName) {
	var conn = null;
	task.logmsg("<!-- compare -->");
	if(ldapcon == null) {
	 conn = initLDAPConn(connName, "Iterator");
	} else {
		// verify that the connector is still ok to use
		try {
			ldapcon.getLdapContext().setRequestControls(null);
			task.logmsg("using the cached connector object: " +ldapcon);
			conn = ldapcon;

		} catch(Ex) {
			task.logmsg("Need to re-initialize the connector");
			ldapcon = null
			conn = initLDAPConn(connName, "Iterator");
		}
	}

	var ent = work.getObject("ldap.entry");

	if(conn != null) {
		try {
			task.logmsg("the compare dn is: " +work.getObject("ldap.dn"));
			task.logmsg("the compareAttr is: " +work.getObject("ldap.compareAttribute"));
			task.logmsg("the compareValue is: " + work.getObject("ldap.compareValue"));
			var res = conn.compare(work.getObject("ldap.dn"), work.getObject("ldap.compareAttribute"), work.getObject("ldap.compareValue"));
			if ( res == true) {
				work.setAttribute("errormessage", "Compare True");
			}else {
				work.setAttribute("errormessage", "Compare False");
			}
			work.setAttribute("ldap.status", "0");
		} catch(Ex) {

			task.logmsg("<!**** compare :: Exception during compare operation ***: > " +Ex);
			work.setAttribute("ldap.status", "1");
		}
	} else {
		task.logmsg("<!*** compare :: connector not initialized for compare operation ***>");
		work.setAttribute("ldap.status", "1");
		return 1;
	}
}

// Utility methods
// -- The memq connector
var memQ = null;

var ldap = null;

// -- The search AL
var searchAL = null;

//
// -- This function creates the search al instance
//
function loadSearchAL() {

	// -- load and init the ldap connector for search
	if(ldapcon == null) {
		task.logmsg("ldapcon is null. Initializing the connector");
		ldap = initLDAPConn("1", "Iterator");
	} else {
		// verify that the connector is still ok to use
		try {
			ldapcon.getLdapContext().setRequestControls(null);
			task.logmsg("using the cached connector object: " +ldapcon);
			ldap = ldapcon;
			ldap.setParam("ldapSearchFilter", work.getObject("ldap.searchfilter"));

		} catch(Ex) {
			task.logmsg("Need to re-initialize the connector");
			ldapcon = null
			ldap = initLDAPConn("1", "Iterator");
		}

	}
	if ( ldap == null ) {
		task.logmsg("no ldapconnector");
		return;
	}

	task.logmsg("<!-- ldapSearchFilter: -->" +work.getObject("ldap.searchfilter"));
	task.logmsg("<!-- ldapUsername: -->" +work.getObject("ldapUsername"));

	// Load and initialize the MemQConnector
	memQ = initMemQConnector("ADDOnly");

	if ( memQ == null ) {
		task.logmsg("<!*** loadSearchAL :: MemQconnector not initialized for search ***>")
		return;
	}


	// -- Create a TCB for the AL to do our search
	var tcb = system.newTCB("searchAL");

	// -- input connector
	task.logmsg("the connector name is: " +ldap.getName());
	tcb.setRuntimeConnector("input", ldap);
	setInputParams(tcb);

	// handle the ldapcontrols
	try {
		ldap.getLdapContext().setRequestControls(getControls());
	} catch(Ex) {
		task.logmsg("setRequestControls: " +Ex);
	}


	// -- output connector
//	tcb.setRuntimeConnector("output", memQ);

	tcb.setConnectorParameter("output","queueName",memQ.getParam("queueName"));

	// -- Change the max read setting of the al to the size limit requested by the client
	sizelimit = work.getObject("ldap.sizelimit").intValue();
	if ( sizelimit >= 0 ) {
		task.logmsg("-- setting AL maxread = " + sizelimit);
		tcb.getAssemblyLineConfig().getSettings().setIntegerParameter("maxread", sizelimit);
	}

	task.logmsg("the ldap connector object is: " +ldap);
	task.logmsg("the ldap connector object is: " +ldapcon);

	// -- Start the Search AL
	return main.startAL(tcb);
}

//
// -- This function sends the search results from the search al to the ldap client
//
function sendResults(ldapServer, maxentries) {

	// -- abandon id
	abid_s = work.getObject("ldap.messageid");
    abid = java.lang.Integer.parseInt(abid_s);

	count = 0;

	// Wait for AL to complete and queue to drain
	while ( searchAL.isAlive() || memQ.hasMore() ) {

		// -- Are we asked to abandon the search operation?
		if ( ldapSrv_listener.connector.isAbandoned(abid) ) {
			task.logmsg("REQUEST ABANDONED: " + abid);
			searchAL.shutdown();
			break;
		}

		// -- Entries ready to send?
		if ( memQ.hasMore() ) {
			e = memQ.getNextEntry();
			ldapServer.connector.putEntry(e);
			count++;
		}

		// -- Exceeded max count then return true if we have more (or may have more) entries to send
		if ( maxentries > 0 && count >= maxentries ) {
			task.logmsg("-- sendReults: read maxentries: " + maxentries);
			task.logmsg("      hasMore: " + memQ.hasMore());
			task.logmsg("      isAlive: " + searchAL.isAlive());
			return memQ.hasMore() || searchAL.isAlive();
		}
	}

	memQ.terminate();

	// End of searchAL iteration and no more in queue
	return false;
}

function setReplyCodes(finished) {
	// -- Check AL exit code
	if ( !finished ) {
		work.setAttribute("ldap.status", "0");
		return;
	}

	err = searchAL.getStats().getError();
	if ( err != null ) {
		task.logmsg ("Search failed: " + err);
		work.setAttribute("ldap.errormessage", err.toString());
		work.setAttribute("ldap.status", "1"); // -- operations error
		err.printStackTrace();
	} else {
		work.setAttribute("ldap.status", "0");
	}
}

/////////////////////////////////////////////////////////////////////////
//	function:	getControls
//	Version:	1.0
//
// 	Description: 
//				gets an array of controls
/////////////////////////////////////////////////////////////////////////

function getControls() {

	ctlsArr = null;

	if(work.getAttribute("ldap.controls") != null) {

		ctls = Packages.java.lang.Class.forName("com.ibm.di.eventhandler.ldap.LDAPControl");
		ctlsArr = Packages.java.lang.reflect.Array.newInstance(ctls, work.getAttribute("ldap.controls").getValues().length);

		cv = work.getAttribute("ldap.controls").getValues();
		for ( i = 0; i < cv.length; i++ ) {
			task.logmsg("cv is: " +cv[i]);
			ctlsArr[i] = cv[i];
		}
		task.logmsg("the controls vector is: " +ctlsArr);
	} else {
		task.logmsg("no controls!!!");
	}
	task.logmsg("the controls array is: " +ctlsArr);
	return ctlsArr;
}

/////////////////////////////////////////////////////////////////////////
//	function:	modRDN
//	Version:	1.0
//
// 	Description: 
//				modify an RDN
/////////////////////////////////////////////////////////////////////////
function modRDN(connName) {
	task.logmsg("<!-- modRDN -->");
	var conn = null;
	if(ldapcon == null) {
	 conn = initLDAPConn(connName, "Iterator");
	} else {
		// verify that the connector is still ok to use
		try {
			ldapcon.getLdapContext().setRequestControls(null);
			task.logmsg("using the cached connector object: " +ldapcon);
			conn = ldapcon;

		} catch(Ex) {
			task.logmsg("Need to re-initialize the connector");
			ldapcon = null
			conn = initLDAPConn(connName, "Iterator");
		}
	}
	var newEnt = system.newEntry();
	newEnt.addAttributeValue( "$dn", work.getAttribute("ldap.dn"));
	var ent = work.getObject("ldap.rdn");
	newEnt.addAttributeValue( "ldap.rdn", ent );

	var searchCriteria = system.newSearchCriteria();
	searchCriteria.addTemplate("$dn", "=", work.getObject("ldap.dn"));
	searchCriteria.buildCriteria(newEnt);

	if(conn != null) {
		try {
			task.logmsg("<!-- modRDN :: entry  -->" +newEnt);
			work.setAttribute("ldap.deleteOldRDN", "true");
			mydn = getNewDN(work.getObject("ldap.dn"), work.getObject("ldap.rdn"));
			conn.moveEntry(work.getObject("ldap.dn"), mydn);
			work.setAttribute("ldap.status", "0");
			return 0; 
		} catch(Ex) {
			task.logmsg("<!**** modRDN :: Exception during ldapmodify operation ***: > " +Ex);
			work.setAttribute("ldap.status", "1");
			return 1;
		}
	} else {
		task.logmsg("<!*** modEntry :: connector not initialized for ldapmodify operation ***>");
		work.setAttribute("ldap.status", "1");
		return 1;
	}
}

/////////////////////////////////////////////////////////////////////////
//	function:	modEntry
//	Version:	1.0
//
// 	Description: 
//				modify an entry
/////////////////////////////////////////////////////////////////////////

function modEntry (connName) {
	var conn = null;
	if(ldapcon == null) {
	 conn = initLDAPConn(connName, "Iterator");
	} else {
		// verify that the connector is still ok to use
		try {
			ldapcon.getLdapContext().setRequestControls(null);
			task.logmsg("using the cached connector object: " +ldapcon);
			conn = ldapcon;

		} catch(Ex) {
			task.logmsg("Need to re-initialize the connector");
			ldapcon = null
			conn = initLDAPConn(connName, "Iterator");
		}
	}
	var newEnt = system.newEntry();
	var ent = work.getObject("ldap.entry");
	var attrnames = ent.getAttributeNames();
	for ( i = 0; i < attrnames.length; i++ ) {
		var attr = ent.getAttribute ( attrnames[i] );
		 if (attr.size() > 1) {
	     	if (attr.getValue(0) == "replace") {
				for ( j = 1; j < attr.size(); j++ ) {
				newEnt.addAttributeValue( attrnames[i], attr.getValue ( j ) );
				}
			} else {
		    var op = 0;
			for ( j = 0; j < attr.size(); j++ ) {
			    if (attr.getValue(j) == "add")
				  op = 1;
			    else if (attr.getValue(j) == "delete")
				  op = 2;
			    else 
				  newEnt.addAttributeValue( attrnames[i], attr.getValue ( j ), op );
		    }
	      }
		}
	}
	/*
	var ent = work.getObject("ldap.entry");
	var attrnames = ent.getAttributeNames();
	for ( i = 0; i < attrnames.length; i++ ) {
 		var attr = ent.getAttribute ( attrnames[i] );
		for ( j = 1; j < attr.size(); j++ ) {
			newEnt.addAttributeValue( attrnames[i], attr.getValue ( j ) );
		}
	}
	*/
	var searchCriteria = system.newSearchCriteria();
	searchCriteria.addTemplate("$dn", "=", work.getAttribute("ldap.dn").getValue());
	searchCriteria.buildCriteria(newEnt);
	if(conn != null) {
		try {
			conn.modEntry(newEnt, searchCriteria);
			task.logmsg("<!-- modEntry :: modify entry  -->" +newEnt);
			work.setAttribute("ldap.status", "0");
			return 0; 
		} catch(Ex) {
			task.logmsg("<!**** modEntry :: Exception during ldapmodify ***: " +Ex);
			work.setAttribute("ldap.status", "1");
			return 1;
		}
	} else {
		task.logmsg("<!*** modEntry :: connector not initialized for ldapmodify operation ***>");
		work.setAttribute("ldap.status", "1");
		return 1;
	}
}

