	return connMode;
}

/////////////////////////////////////////////////////////////////////////
//	function:	putEntry
//	Version:	1.0
//
// 	Description: 
//				add an entry to the ldap server. 
/////////////////////////////////////////////////////////////////////////

function putEntry(connName) {

	task.logmsg("<!-- addThis -->");
	var conn = null;
	if(ldapcon == null) {
	 conn = initLDAPConn(connName, "Iterator");
	} else {
		// verify that the connector is still ok to use
		try {
			ldapcon.getLdapContext().setRequestControls(null);
			task.logmsg("using the cached connector object: " +ldapcon);
			conn = ldapcon;

		} catch(Ex) {
			task.logmsg("Need to re-initialize the connector");
			ldapcon = null
			conn = initLDAPConn(connName, "Iterator");
		}
	}
	var newEnt = system.newEntry();
	var ent = work.getObject("ldap.entry");
	task.logmsg("<!--- the ldap.entry is --->" +ent);
	var attrnames = ent.getAttributeNames();
	for ( i = 0; i < attrnames.length; i++ ) {
 		var attr = ent.getAttribute ( attrnames[i] );
		for ( j = 0; j < attr.size(); j++ ) {
			newEnt.addAttributeValue( attrnames[i], attr.getValue ( j ) );
		}
	}
	if(conn != null) {
		try {
			conn.putEntry(newEnt);
			task.logmsg("<!-- putEntry :: added entry  -->" +newEnt);
			work.setAttribute("ldap.status", "0");
			return 0; 
		} catch(Ex) {
			task.logmsg("<!**** putEntry :: Exception during ldapadd operation ***: " +Ex);
			work.setAttribute("ldap.status", "1");
			return 1;
		}
	} else {
		task.logmsg("<!*** putEntry :: connector not initialized for ldapadd operation ***>");
		work.setAttribute("ldap.status", "1");
		return 1;
	}
}

/////////////////////////////////////////////////////////////////////////
//	function:	delEntry
//	Version:	1.0
//
// 	Description: 
//				modify an entry
/////////////////////////////////////////////////////////////////////////

function delEntry(connName) {
	var conn = null;
	if(ldapcon == null) {
	 conn = initLDAPConn(connName, "Iterator");
	} else {
		// verify that the connector is still ok to use
		try {
			ldapcon.getLdapContext().setRequestControls(null);
			task.logmsg("using the cached connector object: " +ldapcon);
			conn = ldapcon;

		} catch(Ex) {
			task.logmsg("Need to re-initialize the connector");
			ldapcon = null
			conn = initLDAPConn(connName, "Iterator");
		}
	}

	var newEnt = conn.findEntry("$dn",work.getAttribute("ldap.dn").getValue());
	var searchCriteria = system.newSearchCriteria();
	searchCriteria.addTemplate("$dn", "=", work.getAttribute("ldap.dn").getValue());
	searchCriteria.buildCriteria(newEnt);
	if(conn != null) {
		try {
			conn.deleteEntry(newEnt, searchCriteria);
			task.logmsg("<!-- delEntry :: added entry  -->" +newEnt);
			work.setAttribute("ldap.status", "0");
			return 0; 
		} catch(Ex) {
			task.logmsg("<!**** delEntry :: Exception during ldapdelete operation ***: " +Ex);
			work.setAttribute("ldap.status", "1");
			return 1;
		}
	} else {
		task.logmsg("<!*** delEntry :: connector not initialized for ldapdelete operation ***>");
		work.setAttribute("ldap.status", "1");
		work.setAttribute("ldap.status", "1");
		return 1;
	}
}

/////////////////////////////////////////////////////////////////////////
//	function:	initMemQConnector
//	Version:	1.0
//
// 	Description: 
//				Initializes the MemQConnector 
/////////////////////////////////////////////////////////////////////////
function initMemQConnector( memmode ) {
	var connMode = new Packages.com.ibm.di.server.ConnectorMode(memmode);
	var memq = system.loadConnector("memQ");
	memq.setParam("queueName", "LDAPSearch-" + task.hashCode());
    memq.setParam("jdbcTable", "memq");
	memq.initialize(connMode);
	return memq;
}

/////////////////////////////////////////////////////////////////////////
//	function:	getNewDN
//	Version:	1.0
//
// 	Description: 
//				returns a new dn for the modrdn op
/////////////////////////////////////////////////////////////////////////
function getNewDN(olddn, newdn){
	olddn = String(olddn);
	newdn = String(newdn);
	var modrdn = newdn + olddn.substring(olddn.indexOf(","));
	task.logmsg("the modrdn is: " +modrdn);
	return modrdn;
}
